def group_numbers(numbers):
    for k, g in groupby(enumerate(sorted(numbers)), lambda (i, x):i - x):
        first = None
        for last in g:
            if first is None:
                first = last[1]
        yield first, last[1]


class ColumnColor(object):  # {{{

    def __init__(self, formatter):
